import React, { useEffect, useState } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import api from "../api/api";
import { useCart } from "../context/CartContext";

const placeholderImg =
  "data:image/svg+xml;utf8," +
  encodeURIComponent(
    `<svg xmlns='http://www.w3.org/2000/svg' width='600' height='600'><rect width='100%' height='100%' fill='#221D19'/><text x='50%' y='50%' font-family='sans-serif' font-size='18' fill='#8A8177' text-anchor='middle'>Khussa Photo</text></svg>`
  );

const ProductDetail = () => {
  const { slug } = useParams();
  const navigate = useNavigate();
  const { addToCart } = useCart();

  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [size, setSize] = useState(null);
  const [color, setColor] = useState(null);
  const [quantity, setQuantity] = useState(1);
  const [activeImage, setActiveImage] = useState(0);
  const [added, setAdded] = useState(false);

  useEffect(() => {
    setLoading(true);
    api
      .get(`/products/${slug}`)
      .then(({ data }) => {
        setProduct(data);
        setSize(data.sizes?.[0] ?? null);
        setColor(data.colors?.[0] ?? null);
      })
      .catch(() => setError("Product not found."))
      .finally(() => setLoading(false));
  }, [slug]);

  if (loading) return <p className="text-stone text-center py-24">Loading...</p>;
  if (error || !product)
    return (
      <div className="text-center py-24">
        <p className="text-stone mb-4">{error || "Product not found."}</p>
        <Link to="/shop" className="text-brass">Back to shop</Link>
      </div>
    );

  const images = product.images?.length ? product.images : [placeholderImg];

  const handleAddToCart = () => {
    addToCart(product, { size, color, quantity });
    setAdded(true);
    setTimeout(() => setAdded(false), 2000);
  };

  const handleBuyNow = () => {
    addToCart(product, { size, color, quantity });
    navigate("/cart");
  };

  return (
    <div className="max-w-6xl mx-auto px-5 py-16 grid md:grid-cols-2 gap-14">
      <div>
        <div className="aspect-square bg-charcoal border border-brass/10 overflow-hidden">
          <img src={images[activeImage]} alt={product.name} className="w-full h-full object-cover" />
        </div>
        {images.length > 1 && (
          <div className="flex gap-3 mt-3">
            {images.map((img, idx) => (
              <button
                key={idx}
                onClick={() => setActiveImage(idx)}
                className={`w-16 h-16 border ${activeImage === idx ? "border-brass" : "border-brass/10"}`}
              >
                <img src={img} alt="" className="w-full h-full object-cover" />
              </button>
            ))}
          </div>
        )}
      </div>

      <div>
        <p className="text-brass text-xs mb-2">{product.category}</p>
        <h1 className="text-3xl text-ivory mb-3">{product.name}</h1>
        <div className="flex items-center gap-3 mb-6">
          <span className="text-brass text-xl">Rs. {product.price.toLocaleString()}</span>
          {product.compareAtPrice && (
            <span className="text-stone line-through text-sm">
              Rs. {product.compareAtPrice.toLocaleString()}
            </span>
          )}
        </div>
        <p className="text-stone leading-relaxed mb-8">{product.description}</p>

        {product.sizes?.length > 0 && (
          <div className="mb-6">
            <p className="text-sm text-ivory mb-2">Size</p>
            <div className="flex flex-wrap gap-2">
              {product.sizes.map((s) => (
                <button
                  key={s}
                  onClick={() => setSize(s)}
                  className={`w-11 h-11 border text-sm ${
                    size === s ? "border-brass text-brass" : "border-brass/20 text-stone"
                  }`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        )}

        {product.colors?.length > 0 && (
          <div className="mb-6">
            <p className="text-sm text-ivory mb-2">Colour</p>
            <div className="flex flex-wrap gap-2">
              {product.colors.map((c) => (
                <button
                  key={c}
                  onClick={() => setColor(c)}
                  className={`px-4 py-2 border text-sm ${
                    color === c ? "border-brass text-brass" : "border-brass/20 text-stone"
                  }`}
                >
                  {c}
                </button>
              ))}
            </div>
          </div>
        )}

        <div className="mb-8">
          <p className="text-sm text-ivory mb-2">Quantity</p>
          <div className="flex items-center border border-brass/20 w-fit">
            <button
              className="w-10 h-10 text-ivory"
              onClick={() => setQuantity((q) => Math.max(1, q - 1))}
            >
              -
            </button>
            <span className="w-10 text-center text-ivory">{quantity}</span>
            <button className="w-10 h-10 text-ivory" onClick={() => setQuantity((q) => q + 1)}>
              +
            </button>
          </div>
        </div>

        {product.stock === 0 ? (
          <p className="text-maroon">Currently out of stock</p>
        ) : (
          <div className="flex gap-4">
            <button
              onClick={handleAddToCart}
              className="flex-1 border border-brass text-brass py-3 text-sm hover:bg-brass hover:text-ink transition-colors"
            >
              {added ? "Added to cart" : "Add to Cart"}
            </button>
            <button
              onClick={handleBuyNow}
              className="flex-1 bg-brass text-ink py-3 text-sm hover:bg-ivory transition-colors"
            >
              Buy Now
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProductDetail;
